struct PresetFilterOptions {FilterPreset preset=FilterPreset::CrtSubtle;double opacity=1;bool lcd=false;int lcdWidth=1,lcdHeight=1;};
class PresetFilterDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;const Skin& icons_;
 int choice_=0;int lcdWidth_=1,lcdHeight_=1;bool lcdAvailable_=true,updatingNumbers_=false;std::array<double,6> opacity_{{1,.72,1,.35,1,.24}};bool live_=true,busy_=false,queued_=true,closed_=false;
 std::chrono::steady_clock::time_point due_=std::chrono::steady_clock::now()+std::chrono::milliseconds(40);ui::Timer timer_{10,this};
 std::array<PixelButton*,7> choices_{};PixelEntry* lcdSize_[2]{};PixelSlider* opacitySlider_;PixelSwitch* liveControl_;PixelButton *close_,*cancel_,*apply_;std::u32string error_;
 std::function<void(std::optional<PresetFilterOptions>)> preview_;std::function<void(PresetFilterOptions)> applyFn_;std::function<std::optional<bool>()> poll_;
 static const std::array<std::u32string,7>& names(){static const auto n=[] {std::array<std::u32string,7> a;for(int i=0;i<6;++i)a[i]=filterPresetDefinitions()[i].name;a[6]=U"LCD屏幕滤镜";return a;}();return n;}
 static const std::array<std::u32string,7>& descriptions(){static const auto d=[] {std::array<std::u32string,7> a;for(int i=0;i<6;++i)a[i]=filterPresetDefinitions()[i].description;a[6]=U"宽度和高度控制 RGB 通道的位置偏移。";return a;}();return d;}
 PresetFilterOptions options()const{return {choice_==6?FilterPreset::CrtSubtle:FilterPreset(choice_),choice_==6?1:opacity_[choice_],choice_==6,lcdWidth_,lcdHeight_};}
 PixelButton* button(std::u32string title,std::function<void()> fn){auto b=new PixelButton(font_,skin_,std::move(title),std::move(fn));addChild(b);return b;}
 int choiceWidth()const{int w=0;for(auto& n:names())w=std::max(w,font_.measure(n)+12);return w;}
 int minimumWidth()const{return std::max(choiceWidth()+2*DialogLayout::inset,font_.measure(U"实时预览")+36+font_.measure(U"取消")+12+font_.measure(U"应用")+12+4*DialogLayout::gap+2*DialogLayout::inset);}
 int columns(int width)const{return std::clamp((width-2*DialogLayout::inset+DialogLayout::gap)/(choiceWidth()+DialogLayout::gap),1,3);}
 int rows(int width)const{return (7+columns(width)-1)/columns(width);}
 int noteY(int width)const{return DialogLayout::bodyTop+rows(width)*textControlHeight+(rows(width)-1)*DialogLayout::gap+DialogLayout::group;}
 std::vector<std::u32string> noteLines(int width)const{std::vector<std::u32string> result;std::u32string line;for(auto ch:descriptions()[choice_]){auto next=line+ch;if(!line.empty()&&font_.measure(next)>width-2*DialogLayout::inset){result.push_back(line);line.clear();}line+=ch;}if(!line.empty())result.push_back(line);return result;}
 int noteHeight(int width)const{int count=1;for(auto& d:descriptions()){int lines=1,measured=0;for(auto ch:d){const int advance=font_.measure(std::u32string(1,ch));if(measured&&measured+advance>width-2*DialogLayout::inset){++lines;measured=0;}measured+=advance;}count=std::max(count,lines);}return count*(UiSpacing::labelHeight+DialogLayout::gap);}
 int opacityLabelY(int width)const{return noteY(width)+noteHeight(width)+DialogLayout::group;}
 int errorY(int width)const{return opacityLabelY(width)+UiSpacing::labelHeight+DialogLayout::gap+textControlHeight+DialogLayout::group;}
 int requiredHeight(int width)const{return errorY(width)+UiSpacing::labelHeight+DialogLayout::group+textControlHeight+DialogLayout::inset;}
 void sync(){for(int i=0;i<7;++i){choices_[i]->active=i==choice_;choices_[i]->setEnabled(!busy_&&(i!=6||lcdAvailable_));choices_[i]->invalidate();}opacitySlider_->setVisible(choice_!=6);if(choice_!=6)opacitySlider_->value=int(std::floor(opacity_[choice_]*100+.5));opacitySlider_->setEnabled(!busy_);opacitySlider_->invalidate();updatingNumbers_=true;for(int i=0;i<2;++i){lcdSize_[i]->setVisible(choice_==6);lcdSize_[i]->setEnabled(!busy_);lcdSize_[i]->setText(std::to_string(i?lcdHeight_:lcdWidth_));}updatingNumbers_=false;liveControl_->setChecked(live_);liveControl_->setEnabled(!busy_);close_->setEnabled(!busy_);cancel_->setEnabled(!busy_);apply_->setEnabled(!busy_);invalidate();}
 void sizeChanged(int axis,bool commit){if(updatingNumbers_||busy_)return;auto e=lcdSize_[axis];try{if(commit&&!e->commitExpression())throw std::runtime_error("Invalid LCD size");std::size_t used=0;const double value=std::stod(e->text(),&used);if(used!=e->text().size()||!std::isfinite(value)){if(commit)sync();return;}const int n=int(std::clamp(std::floor(value+.5),1.,64.));auto& target=axis?lcdHeight_:lcdWidth_;if(target!=n){target=n;const auto editing=e->text();schedule();if(!commit)e->setText(editing);}}catch(...){if(commit)sync();}if(commit)sync();}
 void schedule(){queued_=true;due_=std::chrono::steady_clock::now()+std::chrono::milliseconds(40);error_.clear();sync();}
 void cancel(){if(busy_)return;queued_=false;closed_=true;timer_.stop();if(preview_)preview_(std::nullopt);closeWindow(nullptr);}
 void apply(){if(busy_)return;if(choice_==6){sizeChanged(0,true);sizeChanged(1,true);}queued_=false;busy_=true;error_.clear();sync();try{applyFn_(options());}catch(const std::exception& e){busy_=false;error_=unicodeText(e.what());sync();}}
 void tick(){if(closed_)return;try{if(poll_){auto applied=poll_();if(applied){if(*applied){closed_=true;timer_.stop();closeWindow(nullptr);return;}busy_=false;error_=U"滤镜应用失败，请重试";sync();}}if(queued_&&!busy_&&std::chrono::steady_clock::now()>=due_){queued_=false;preview_(live_?std::optional<PresetFilterOptions>(options()):std::nullopt);}}catch(const std::exception& e){busy_=false;error_=unicodeText(e.what());sync();}}
public:
 PresetFilterDialog(const PixelFont& font,const Skin& skin,const Skin& icons,FilterPreset initial,std::function<void(std::optional<PresetFilterOptions>)> preview,std::function<void(PresetFilterOptions)> apply,std::function<std::optional<bool>()> poll,bool lcdAvailable=true,bool initialLcd=false)
 :PixelDialog(skin,"",ClickBehavior::DoNothingOnClick,EnterBehavior::DoNothingOnEnter),font_(font),skin_(skin),icons_(icons),choice_(initialLcd?6:int(initial)),lcdAvailable_(lcdAvailable),preview_(std::move(preview)),applyFn_(std::move(apply)),poll_(std::move(poll)){
 if(choice_<0||choice_>=7||(choice_==6&&!lcdAvailable_))throw std::invalid_argument("Unavailable filter choice");for(int i=0;i<6;++i)opacity_[i]=filterPresetDefinitions()[i].opacity;setAutoRemap(false);setWantFocus(true);
 for(int i=0;i<7;++i)choices_[i]=button(names()[i],[this,i]{if(busy_||(i==6&&!lcdAvailable_))return;choice_=i;schedule();});
 opacitySlider_=new PixelSlider(font,skin);addChild(opacitySlider_);opacitySlider_->minimum=0;opacitySlider_->maximum=100;opacitySlider_->percentage=true;opacitySlider_->changed=[this](int v){if(busy_||choice_==6)return;opacity_[choice_]=std::clamp(v,0,100)/100.;schedule();};
 for(int i=0;i<2;++i){auto e=new PixelEntry(font,skin);addChild(e);lcdSize_[i]=e;e->numeric=true;e->numericStep=1;e->suffix=U"px";e->Change.connect([this,i]{sizeChanged(i,false);});e->blur=[this,i]{sizeChanged(i,true);};e->accept=[this]{this->apply();};e->cancel=[this]{cancel();};}
 liveControl_=new PixelSwitch(font,skin,U"实时预览",true,[this](bool value){if(busy_)return;live_=value;schedule();});addChild(liveControl_);liveControl_->iconSkin=&icons_;liveControl_->icon="eye";
 close_=button(U"",[this]{cancel();});close_->iconSkin=&icons_;close_->icon="close";close_->skinStyle="icon_button";
 cancel_=button(U"取消",[this]{cancel();});apply_=button(U"应用",[this]{this->apply();});timer_.Tick.connect([this]{tick();});sync();}
 ~PresetFilterDialog(){timer_.stop();if(preview_)preview_(std::nullopt);}
 int preferredWidth()const{return std::max(minimumWidth(),2*choiceWidth()+3*DialogLayout::gap+2*DialogLayout::inset);}
 int preferredHeight(int physicalWidth)const{return requiredHeight(physicalWidth/uiScale)*uiScale;}
 gfx::Size minimumDialogSize(int physicalWidth)const override{const int width=std::max(minimumWidth(),physicalWidth/uiScale);return {minimumWidth()*uiScale,requiredHeight(width)*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();const int w=r.w/uiScale,h=r.h/uiScale,col=columns(w);auto place=[&](ui::Widget* c,int x,int y,int width,int height){c->setBounds({r.x+x*uiScale,r.y+y*uiScale,width*uiScale,height*uiScale});};layoutHeaderButton(close_);const int body=w-2*DialogLayout::inset,cell=(body-(col-1)*DialogLayout::gap)/col;for(int i=0;i<7;++i)place(choices_[i],DialogLayout::inset+(i%col)*(cell+DialogLayout::gap),DialogLayout::bodyTop+(i/col)*DialogLayout::rowStep,cell,textControlHeight);place(opacitySlider_,DialogLayout::inset,opacityLabelY(w)+UiSpacing::labelHeight+DialogLayout::gap,body,textControlHeight);const int half=(body-DialogLayout::gap)/2;for(int i=0;i<2;++i)place(lcdSize_[i],DialogLayout::inset+i*(half+DialogLayout::gap),opacityLabelY(w)+UiSpacing::labelHeight+DialogLayout::gap,i?body-half-DialogLayout::gap:half,textControlHeight);const int y=DialogLayout::footer(h),applyWidth=font_.measure(U"应用")+12,cancelWidth=font_.measure(U"取消")+12;place(apply_,w-DialogLayout::inset-applyWidth,y,applyWidth,textControlHeight);place(cancel_,w-DialogLayout::inset-applyWidth-DialogLayout::gap-cancelWidth,y,cancelWidth,textControlHeight);place(liveControl_,DialogLayout::inset,y,font_.measure(U"实时预览")+36,textControlHeight);}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,U"滤镜");int y=noteY(r.w);for(auto& line:noteLines(r.w)){font_.draw(g,line,r.x+DialogLayout::inset,r.y+y,skin_["muted"]);y+=UiSpacing::labelHeight+DialogLayout::gap;}if(choice_==6){const int half=(r.w-2*DialogLayout::inset-DialogLayout::gap)/2;font_.draw(g,U"宽",r.x+DialogLayout::inset,r.y+opacityLabelY(r.w),skin_["text"]);font_.draw(g,U"高",r.x+DialogLayout::inset+half+DialogLayout::gap,r.y+opacityLabelY(r.w),skin_["text"]);}else font_.draw(g,U"不透明度",r.x+DialogLayout::inset,r.y+opacityLabelY(r.w),skin_["text"]);if(!error_.empty()){g.saveClip();g.clipRect({r.x+DialogLayout::inset,r.y+errorY(r.w),r.w-2*DialogLayout::inset,UiSpacing::labelHeight});font_.draw(g,error_,r.x+DialogLayout::inset,r.y+errorY(r.w),skin_["text"]);g.restoreClip();}}
 bool onProcessMessage(ui::Message* msg)override{if(msg->type()==ui::kOpenMessage){timer_.start();choices_[choice_]->requestFocus();}if(msg->type()==ui::kCloseMessage){timer_.stop();queued_=false;}if(msg->type()==ui::kKeyDownMessage){const auto key=static_cast<ui::KeyMessage*>(msg);if(key->scancode()==ui::kKeyEsc){cancel();return true;}if(key->scancode()==ui::kKeyEnter){apply();return true;}}if(msg->type()==ui::kMouseDownMessage&&!busy_){const auto mouse=static_cast<ui::MouseMessage*>(msg);if(mouse->left()&&!bounds().contains(mouse->position())){cancel();return true;}}return PixelPopupWindow::onProcessMessage(msg);}
 bool busy()const{return busy_;}
 PresetFilterOptions currentOptions()const{return options();}
 void smokeStep(int step){auto check=[](bool b,const char* why){if(!b)throw std::runtime_error(why);};if(step==0){check(live_&&!busy_,"Preset filter live default");for(int i=0;i<6;++i){choices_[i]->Click();check(choice_==i,"Preset filter choice");const double defaults[]{1,.72,1,.35,1,.24};check(std::abs(opacity_[i]-defaults[i])<1e-9,"Preset filter opacity defaults");}choices_[5]->Click();opacitySlider_->changed(50);choices_[4]->Click();check(opacitySlider_->value==100,"Preset filter opacity independent");choices_[5]->Click();check(opacitySlider_->value==50,"Preset filter opacity retained");liveControl_->Click();check(!live_,"Preset filter live disabled");}else if(step==1){liveControl_->Click();check(live_,"Preset filter live restored");}else if(step==2)cancel_->Click();else if(step==3){apply_->Click();check(busy_,"Preset filter async apply busy");} }
 void smokeLcdStep(int step){auto check=[](bool yes,const char* why){if(!yes)throw std::runtime_error(why);};if(step==0){check(choice_==6&&lcdAvailable_&&live_&&!busy_,"LCD initial choice/live");check(lcdWidth_==1&&lcdHeight_==1&&!opacitySlider_->isVisible()&&lcdSize_[0]->isVisible()&&lcdSize_[1]->isVisible(),"LCD width-height defaults");lcdSize_[0]->setText("0");lcdSize_[0]->Change();check(lcdWidth_==1,"LCD minimum");lcdSize_[0]->setText("64.7");lcdSize_[0]->Change();check(lcdWidth_==64,"LCD maximum/round");lcdSize_[0]->setText("2");lcdSize_[0]->Change();lcdSize_[1]->setText("3");lcdSize_[1]->Change();for(int i=0;i<6;++i){choices_[i]->Click();check(choice_==i&&opacitySlider_->isVisible()&&!lcdSize_[0]->isVisible(),"LCD shared presets");}choices_[6]->Click();check(currentOptions().lcd&&lcdWidth_==2&&lcdHeight_==3&&!opacitySlider_->isVisible(),"LCD retained dimensions");liveControl_->Click();check(!live_,"LCD disable live");}else if(step==1){liveControl_->Click();check(live_,"LCD restore live");}else if(step==2)cancel_->Click();else if(step==3){apply_->Click();check(busy_,"LCD async busy");}}

};
